mod dashboard;
mod events;
mod format;
mod home;
mod icons;
mod lab;
mod layout;
mod node;
mod nodes;
mod overview;
mod panel;
mod remotes;
mod rules;
mod settings;
mod toasts;

use std::sync::Arc;

use topcoat::{
    Result,
    router::{
        Router,
        content::{Css, Js},
        route,
    },
};

use crate::hub::Hub;

const HTMX: &str = include_str!("../../static/htmx.min.js");
const HTMX_SSE: &str = include_str!("../../static/htmx-ext-sse.min.js");
const NODE_FILTER: &str = include_str!("../../static/node-filter.js");
/// Generated by build.rs from styles.css.
const STYLESHEET: &str = include_str!(concat!(env!("OUT_DIR"), "/tailwind.css"));

pub fn router(hub: Arc<Hub>) -> Router {
    Router::builder()
        .page(dashboard::dashboard_page)
        .page(dashboard::dashboard_fragment)
        .page(nodes::nodes_page)
        .page(nodes::nodes_fragment)
        .page(node::node_page)
        .page(node::overview_fragment)
        .page(node::overview_edit_fragment)
        .page(node::fields_fragment)
        .page(node::fields_edit_fragment)
        .page(panel::panel)
        .page(rules::rules)
        .page(remotes::remotes_page)
        .page(remotes::remotes_fragment)
        .page(settings::settings)
        .page(settings::settings_file)
        .page(lab::lab)
        .route(home::set)
        .route(node::edit)
        .route(home::invoke)
        .route(remotes::learn_key)
        .route(panel::press)
        .route(settings::reload)
        .route(settings::save)
        .route(toasts::toasts)
        .route(events::events)
        .route(htmx_script)
        .route(htmx_sse_script)
        .route(node_filter_script)
        .route(stylesheet)
        .app_context(hub)
        .build()
}

#[route(GET "/static/htmx.min.js")]
async fn htmx_script() -> Result<Js<&'static str>> {
    Ok(Js(HTMX))
}

#[route(GET "/static/htmx-ext-sse.min.js")]
async fn htmx_sse_script() -> Result<Js<&'static str>> {
    Ok(Js(HTMX_SSE))
}

#[route(GET "/static/node-filter.js")]
async fn node_filter_script() -> Result<Js<&'static str>> {
    Ok(Js(NODE_FILTER))
}

#[route(GET "/static/app.css")]
async fn stylesheet() -> Result<Css<&'static str>> {
    Ok(Css(STYLESHEET))
}
